import React, { useState, useEffect } from 'react';
import './ProfilePage.css'; // No changes to CSS
import { useNavigate } from 'react-router-dom';

const ProfilePage = () => {
  const navigate = useNavigate();

  const navigateToHome = () => navigate('/homes');
  const navigateToChat = () => navigate('/chat');
  const navigateToproj = () => navigate('/ong-proj');
  const navigateToPost = () => navigate('/post');
  const navigateContact = () => navigate('/contact');
  const navigateToAbout = () => navigate('/abt');

  // State for profile data
  const [profile, setProfile] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [tempProfile, setTempProfile] = useState(null);
  const [loading, setLoading] = useState(true);

  // Fetch profile data from API
  useEffect(() => {
    fetch('/api/profile') 
      .then((res) => res.json())
      .then((data) => {
        setProfile(data);
        setTempProfile(data);
        setLoading(false);
      })
      .catch((err) => console.error('Error fetching profile:', err));
  }, []);

  const handleEdit = () => {
    if (isEditing) {
      // Save changes to backend
      fetch('/api/profile', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(tempProfile),
      })
      .then((res) => res.json())
      .then((updatedProfile) => setProfile(updatedProfile))
      .catch((err) => console.error('Error updating profile:', err));
    }
    setIsEditing(!isEditing);
  };

  const handleChange = (field, value) => {
    setTempProfile({ ...tempProfile, [field]: value });
  };

  if (loading) return <p>Loading...</p>;

  return (
    <div className="profile-page">
      {/* Header */}
      <div className="header">
        <img src="images/image10.png" alt="User" />
        <div className="header-right">
          <span onClick={navigateToHome}>Home</span>
          <span onClick={navigateContact}>Contact Us</span>
          <span onClick={navigateToAbout}>About</span>
          <span onClick={navigateToChat}>Chat</span>
          <span onClick={navigateToproj}>Ongoing Projects</span>
          <span onClick={navigateToPost}>Post a Job</span>
          <span>Settings</span>
        </div>
      </div>

      {/* Main Content */}
      <div className="main-content">
        {/* Profile Card */}
        <div className="profile-card">
          <div className="card-border-top"></div>
          <div className="img">
            <img src={profile.profilePhoto} alt="User" />
          </div>
          <span>{profile.name}</span>
          <span className="job">{profile.skills.join(', ')}</span>
          <span>Rating: {profile.rating} ⭐</span>
          <button onClick={handleEdit}>{isEditing ? 'Save' : 'Edit'}</button>
        </div>

        {/* Achievements */}
        <div className="achievements-section">
          <h2>Achievements</h2>
          {profile.achievements.map((achievement, index) => (
            <div key={index}>
              <div className="content">
                <h3>{achievement.title}</h3>
                <p className="para">{achievement.description}</p>
              </div>
            </div>
          ))}
        </div>

        {/* Financial Overview */}
        <div className="financial-container">
          <h2>Financial Overview</h2>
          <div className="financial-item">
            <span className="label">Platform Coins Earned:</span>
            <span className="value">{profile.coins} Coins</span>
          </div>
          <div className="financial-item">
            <span className="label">Money Received Till Now:</span>
            <span className="value">${profile.moneyReceived}</span>
          </div>
          <div className="financial-item">
            <span className="label">Money in Escrow System:</span>
            <span className="value">${profile.escrowMoney}</span>
          </div>
        </div>

        {/* Reviews */}
        <div className="reviews-section">
          <h2>Reviews Received</h2>
          <div className="reviews-card">
            {profile.reviews.map((review, index) => (
              <div key={index} className="review-item">
                <h3>{review.reviewer}</h3>
                <p>"{review.comment}"</p>
                <span>{'⭐'.repeat(review.rating)}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Edit Modal */}
        {isEditing && (
          <div className="edit-modal">
            <h2>Edit Profile</h2>
            <input
              type="text"
              value={tempProfile.name}
              onChange={(e) => handleChange('name', e.target.value)}
              placeholder="Full Name"
            />
            <input
              type="email"
              value={tempProfile.email}
              onChange={(e) => handleChange('email', e.target.value)}
              placeholder="Email"
            />
            <input
              type="password"
              value={tempProfile.password}
              onChange={(e) => handleChange('password', e.target.value)}
              placeholder="Password"
            />
            <input
              type="text"
              value={tempProfile.profilePhoto}
              onChange={(e) => handleChange('profilePhoto', e.target.value)}
              placeholder="Profile Photo URL"
            />
            <textarea
              value={tempProfile.bio}
              onChange={(e) => handleChange('bio', e.target.value)}
              placeholder="Tell about yourself (max 100 words)"
              maxLength="100"
            />
          </div>
        )}
      </div>
    </div>
  );
};

export default ProfilePage;
